#include <bits/stdc++.h>
using namespace std;

const int MAXNODES = 10000;
const int MAXEDGES = 2000000;
const int INF = 0x3f3f3f3f;

int node_count, edge_count, max_flow_value, total_cost_value;

struct Edge
{
    int to, next, capacity, flow, cost;
} edge_array[MAXEDGES];
int head_array[MAXNODES], edge_index;
int parent_node[MAXNODES], dist_array[MAXNODES];
bool in_queue_flag[MAXNODES];
int total_nodes;

void setup(int n)
{
    total_nodes = n;
    edge_index = 0;
    memset(head_array, -1, sizeof(head_array));
}
void add_edge(int u, int v, int cap, int cst)
{
    edge_array[edge_index].to = v;
    edge_array[edge_index].capacity = cap;
    edge_array[edge_index].cost = cst;
    edge_array[edge_index].flow = 0;
    edge_array[edge_index].next = head_array[u];
    head_array[u] = edge_index++;
    edge_array[edge_index].to = u;
    edge_array[edge_index].capacity = 0;
    edge_array[edge_index].cost = -cst;
    edge_array[edge_index].flow = 0;
    edge_array[edge_index].next = head_array[v];
    head_array[v] = edge_index++;
}
bool spfa_check(int s, int t)
{
    queue<int> q;
    for (int i = 0; i < total_nodes; i++)
    {
        dist_array[i] = INF;
        in_queue_flag[i] = false;
        parent_node[i] = -1;
    }
    dist_array[s] = 0;
    in_queue_flag[s] = true;
    q.push(s);
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        in_queue_flag[u] = false;
        for (int i = head_array[u]; i != -1; i = edge_array[i].next)
        {
            int v = edge_array[i].to;
            if (edge_array[i].capacity > edge_array[i].flow && dist_array[v] > dist_array[u] + edge_array[i].cost)
            {
                dist_array[v] = dist_array[u] + edge_array[i].cost;
                parent_node[v] = i;
                if (!in_queue_flag[v])
                {
                    in_queue_flag[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return parent_node[t] != -1;
}
int execute_min_cost_flow(int s, int t, int &total_cost)
{
    int total_flow = 0;
    total_cost = 0;
    while (spfa_check(s, t))
    {
        int flow_cap = INF;
        for (int i = parent_node[t]; i != -1; i = parent_node[edge_array[i ^ 1].to])
        {
            if (flow_cap > edge_array[i].capacity - edge_array[i].flow)
                flow_cap = edge_array[i].capacity - edge_array[i].flow;
        }
        for (int i = parent_node[t]; i != -1; i = parent_node[edge_array[i ^ 1].to])
        {
            edge_array[i].flow += flow_cap;
            edge_array[i ^ 1].flow -= flow_cap;
            total_cost += edge_array[i].cost * flow_cap;
        }
        total_flow += flow_cap;
    }
    return total_flow;
}

int main()
{
    cin >> n >> m >> k >> c >> d;
    setup(MAXNODES);
    for(int i = 0; i < k; i++)
    {
        int x;
        cin >> x;
        add_edge(0, x, 1, 0);
    }
    for(int i = 0; i < 100; i++)
    {
        for(int j = 0; j < k; j++)
            add_edge(1+i*n, 9999, 1, i*c);
    }
    for(int i = 0; i < m; i++)
    {
        int u, v;
        cin >> u >> v;
        for(int j = 1; j < 100; j++)
        {
            for(int gg = 1; gg <= k; gg++)
            {
                add_edge(u+(j-1)*n, v+j*n, 1, (2*gg-1)*d);
                add_edge(v+(j-1)*n, u+j*n, 1, (2*gg-1)*d);
            }
        }
    }
    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j < 100; j++)
        {
            add_edge(i+(j-1)*n, i+j*n, k, 0);
        }
    }

    int total_cost;
    execute_min_cost_flow(0, 9999, total_cost);
    cout << total_cost << endl;
}
